import Foundation
#if canImport(SQLite3)
import SQLite3
#else
import CSQLite
#endif
import Testing
import WorkspaceFixtures
import WovenMatterCore
@testable import WovenMatterDashboardStore

/// The migration of the maintainer's real libraries: every Mac and Linux host
/// that updates opens a `workspace.sqlite` written by v0.4.2. The fixture is
/// that schema exactly as v0.4.2 creates it (generated by running the tag's
/// own code; see its header), with a native chat whose run recorded its native
/// harness session, OpenClaw dashboard-era rows and tables, and the paired-sync
/// bookkeeping v0.4.2's triggers wrote for them. Opening it with this build
/// must give the same schema a fresh library has, keep the data that still
/// means something, and leave peer bookkeeping on the new names.
@Suite struct LibrarySchemaUpgradeTests {
  @Test func aV042LibraryOpensWithTheCurrentSchemaAndKeepsItsData() async throws {
    let upgraded = try PersistenceFixture(), fresh = try PersistenceFixture()
    defer { upgraded.remove(); fresh.remove() }
    let fixture = URL(fileURLWithPath: #filePath).deletingLastPathComponent()
      .appending(path: "../Fixtures/library-v0.4.2.sql").standardizedFileURL
    try PersistenceSQL(url: upgraded.databaseURL).execute(try String(contentsOf: fixture, encoding: .utf8))
    // Open both the way the app does: the usage index first, then the library.
    _ = try UsageStore(databaseURL: upgraded.databaseURL)
    _ = try UsageStore(databaseURL: fresh.databaseURL)
    let library = try await WorkspaceDatabase(url: upgraded.databaseURL)
    let current = try await WorkspaceDatabase(url: fresh.databaseURL)

    // One schema. A converted table keeps its physical column order and
    // SQLite's quoting of renamed names, so tables are compared by their
    // columns and foreign keys; indexes and triggers, which this build
    // creates, by their SQL.
    let expected = try await schema(current), actual = try await schema(library)
    #expect(actual.keys.sorted() == expected.keys.sorted())
    for key in expected.keys.sorted() where actual[key] != expected[key] {
      Issue.record("\(key) differs:\nupgraded: \(actual[key] ?? "missing")\nfresh: \(expected[key]!)")
    }
    #expect(try await library.pairedLibrarySchema() == current.pairedLibrarySchema())
    // Opening it again changes nothing.
    let reopened = try await schema(WorkspaceDatabase(url: upgraded.databaseURL))
    for key in Set(reopened.keys).union(actual.keys).sorted() where reopened[key] != actual[key] {
      Issue.record("\(key) changed on reopening:\n\(reopened[key] ?? "missing")\nwas: \(actual[key] ?? "missing")")
    }

    // The native chat, its run's native session and its transcript survive.
    let chat = try #require(try await row(library, "SELECT id FROM conversations WHERE title='Native chat'")["id"]?.stringValue)
    #expect(try await row(library, "SELECT native_session_id FROM harness_sessions WHERE conversation_id=?", chat)["native_session_id"]?.stringValue == "native-session-1")
    let run = try await row(library, "SELECT id,native_session_id,status FROM runs WHERE conversation_id=?", chat)
    #expect(run["native_session_id"]?.stringValue == "native-session-1" && run["status"]?.stringValue == "completed")
    #expect(try await rows(library, "SELECT content FROM messages WHERE conversation_id=? ORDER BY created_at", chat)
      .compactMap { $0["content"]?.stringValue } == ["List the files", "Here are the files."])
    #expect(try await rows(library, "SELECT id FROM run_activities WHERE conversation_id=?", chat).count == 1)
    #expect(try await row(library, "SELECT title FROM notes")["title"]?.stringValue == "Plan")
    #expect(try await row(library, "SELECT name FROM folders")["name"]?.stringValue == "Project")
    let content = try await library.conversationContent(id: chat)
    #expect(content.messages.count == 2 && content.runs.count == 1)

    // The dashboard chat stays readable as retained history; the platform
    // chat v0.4.2 never listed stays hidden; the gateway's own rows are gone.
    let listed = Set(try await library.workspaceOverview().conversations.map(\.title))
    #expect(listed == ["Native chat", "Dashboard chat"])
    #expect(try await rows(library, "SELECT conversation_id FROM retained_execution_history").compactMap { $0["conversation_id"]?.stringValue } == ["dashboard-chat"])
    #expect(try await row(library, "SELECT is_archived FROM conversations WHERE id='platform-chat'")["is_archived"]?.intValue == 1)
    #expect(try await row(library, "SELECT imported_at FROM session_imports WHERE conversation_id='dashboard-chat'")["imported_at"] != nil)
    #expect(try await library.conversationContent(id: "dashboard-chat").messages.map(\.content) == ["From the dashboard"])
    #expect(try await row(library, "SELECT deleted_at FROM agents WHERE id='gateway-agent'")["deleted_at"]?.stringValue != nil)
    #expect(try await rows(library, "SELECT id FROM surface_profiles WHERE id LIKE 'web:%'").isEmpty)
    #expect(try await rows(library, "SELECT id FROM activity_summaries WHERE id LIKE 'trace-%'").isEmpty)

    // Peer bookkeeping names the new tables and columns only, and a settled
    // row's recorded versions carry its settled value.
    let peer = try await rows(library, """
      SELECT table_name,payload FROM paired_library_rows
      UNION ALL SELECT json_extract(payload,'$.table'),payload FROM paired_library_changes
      """)
    let tables = Set(peer.compactMap { $0["table_name"]?.stringValue })
    #expect(tables.isSuperset(of: ["runs", "conversations", "messages", "agents", "run_activities"]))
    #expect(tables.allSatisfy { !$0.hasPrefix("dashboard_") && !$0.hasPrefix("desktop_") && $0 != "profiles" })
    for payload in peer.compactMap({ $0["payload"]?.stringValue }) {
      for column in ["user_id", "governing_plane", "authority_kind", "authority_agent_id", "authority_device_id",
                     "origin_device_id", "desktop_owned", "openclaw_session_key", "gateway_media_ref"] {
        #expect(!payload.contains("\"\(column)\""), "\(column) in \(payload.prefix(120))")
      }
    }
    let runID = try #require(run["id"]?.stringValue)
    #expect(try await row(library, "SELECT json_extract(payload,'$.row.native_session_id.value') AS value FROM paired_library_rows WHERE table_name='runs' AND record_key=?", "[\"\(runID)\"]")["value"]?.stringValue == "native-session-1")
    #expect(try await row(library, "SELECT json_extract(payload,'$.row.is_archived.value') AS value FROM paired_library_rows WHERE table_name='conversations' AND record_key='[\"platform-chat\"]'")["value"]?.stringValue == "1")
    #expect(try await rows(library, "SELECT table_name FROM paired_library_seeded WHERE table_name LIKE 'dashboard%' OR table_name LIKE 'desktop%' OR table_name='profiles'").isEmpty)
    #expect(try await rows(library, "SELECT name FROM paired_library_state").isEmpty)

    // The converted library keeps working and syncing under its new names.
    try await library.updateLocalACPSessionID(conversationID: chat, sessionID: "native-session-2")
    let next = try await library.beginLocalACPRun(conversationID: chat, input: .init(text: "Again"))
    #expect(try await row(library, "SELECT native_session_id FROM runs WHERE id=?", next.runID)["native_session_id"]?.stringValue == "native-session-2")
    #expect(try await row(library, "SELECT payload FROM paired_library_changes ORDER BY cursor DESC LIMIT 1")["payload"] != nil)
  }

  private func schema(_ database: WorkspaceDatabase) async throws -> [String: String] {
    try await database.read { connection in
      var result: [String: String] = [:]
      for object in try connection.historyRowsUnlocked("""
        SELECT type,name,sql FROM sqlite_master WHERE sql IS NOT NULL
          AND name NOT LIKE 'sqlite\\_%' ESCAPE '\\' AND name NOT LIKE 'workspace\\_history\\_search\\_%' ESCAPE '\\'
        """, values: []).compactMap(\.objectValue) {
        guard let type = object["type"]?.stringValue, let name = object["name"]?.stringValue,
              let sql = object["sql"]?.stringValue else { continue }
        if type == "table", !sql.hasPrefix("CREATE VIRTUAL") {
          let columns = try connection.historyRowsUnlocked("SELECT name,type,\"notnull\",dflt_value,pk FROM pragma_table_xinfo(?)", values: [name])
            .map { row in ["name", "type", "notnull", "dflt_value", "pk"].map { describe(row.objectValue?[$0]) }.joined(separator: " ") }.sorted()
          let keys = try connection.historyRowsUnlocked("SELECT \"table\",\"from\",\"to\",on_delete FROM pragma_foreign_key_list(?)", values: [name])
            .map { row in ["table", "from", "to", "on_delete"].map { describe(row.objectValue?[$0]) }.joined(separator: " ") }.sorted()
          result["table " + name] = (columns + keys.map { "references " + $0 }).joined(separator: "\n")
        } else {
          result[type + " " + name] = sql.split(whereSeparator: \.isWhitespace).joined(separator: " ")
        }
      }
      return result
    }
  }

  private func describe(_ value: JSONValue?) -> String {
    switch value {
    case .string(let text): text
    case .number(let number): String(number)
    case .bool(let flag): String(flag)
    default: "null"
    }
  }

  private func rows(_ database: WorkspaceDatabase, _ sql: String, _ values: String...) async throws -> [[String: JSONValue]] {
    try await database.read { try $0.historyRowsUnlocked(sql, values: values).compactMap(\.objectValue) }
  }

  private func row(_ database: WorkspaceDatabase, _ sql: String, _ values: String...) async throws -> [String: JSONValue] {
    try await database.read { try $0.historyRowsUnlocked(sql, values: values).first?.objectValue ?? [:] }
  }
}
